import random
random.seed(42)          # fixed seed so the output is repeatable
secret = random.randint(1, 20)

for guess in [10, 15, 3, secret]:
    if guess < secret:
        print(guess, "-> too low")
    elif guess > secret:
        print(guess, "-> too high")
    else:
        print(guess, "-> correct!")

